 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Horizontal strokes are rows with multiple separated colored runs. For
    # each color, close only the gaps between its leftmost and rightmost cells.
    horizontal_rows = []
    for r, row in enumerate(grid):
        colors = [c for c in set(row) if c != 0]
        if sum(v != 0 for v in row) < 4 or len(colors) > 2:
            continue
        # Rows with enough horizontal extent are the horizontal bars.
        if max(i for i, v in enumerate(row) if v) - min(i for i, v in enumerate(row) if v) < 5:
            continue
        horizontal_rows.append(r)
        for color in colors:
            cols = [i for i, v in enumerate(row) if v == color]
            for c in range(min(cols), max(cols) + 1):
                if out[r][c] == 0:
                    out[r][c] = color

    if not horizontal_rows:
        return out

    # Vertical stems are the colored pixels below the lowest horizontal bar.
    bottom_bar = max(horizontal_rows)
    stem_cols = [c for c in range(w) if any(grid[r][c] != 0 for r in range(bottom_bar + 1, h))]

    # At each bar crossed by a stem, its horizontal color becomes the vertical
    # color above that bar, up to the next crossing.
    for c in stem_cols:
        events = []
        for r in horizontal_rows:
            if grid[r][c] != 0:
                color = grid[r][c]
            else:
                color = 0
                for k in range(c - 1, -1, -1):
                    if grid[r][k] != 0:
                        color = grid[r][k]
                        break
                # Only infer across the bar if the column lies within its span.
                nonzero = [i for i, v in enumerate(grid[r]) if v != 0]
                if not nonzero or not (min(nonzero) <= c <= max(nonzero)):
                    color = 0
            if color:
                events.append((r, color))
        events.sort()
        if not events:
            continue
        # Above the topmost crossing takes that crossing's color.
        for r in range(0, events[0][0] + 1):
            out[r][c] = events[0][1]
        # Between crossings, the lower crossing supplies the connecting segment.
        for (upper_r, _), (lower_r, lower_color) in zip(events, events[1:]):
            for r in range(upper_r + 1, lower_r + 1):
                out[r][c] = lower_color
    return out
